async function overzichtCat(m, all, c) {
  const K = await import('./kz.js'); const T = OVT[m.id] || OVT.us; const base = 'https://' + m.host;
  const inCat = all.filter(i => catSlugW(i.cat) === c); if (!inCat.length) return null;
  const naam = inCat[0].cat; let pop = []; try { pop = rankUsage(await Promise.all(usageDays().map(d => dailyUsage(m.id, d))), inCat); } catch (e) {}
  const volg = pop.concat(inCat.slice().sort((a, b) => (b.priority || 0) - (a.priority || 0) || String(b.publishAt || '').localeCompare(String(a.publishAt || ''))).filter(i => !pop.includes(i)));
  const snel = volg.slice(0, volg.length > 9 ? 6 : 3), rest = volg.filter(i => !snel.includes(i));
  const kaart = i => K.ovKaart('/' + i.slug, '', String(i.title).length <= 60 ? i.title : naamW(i), i.kort || i.intro, '');
  const faq = volg.map(i => (i.faq || [])[0] && { q: i.faq[0].q, a: i.faq[0].a, pad: '/' + i.slug, titel: naamW(i) }).filter(f => f && f.q && f.a).filter((f, k, a) => a.findIndex(x => x.q === f.q) === k).slice(0, 8);
  const cats = [...new Set(all.map(i => i.cat))].sort((a, b) => a.localeCompare(b, m.id === 'de' ? 'de' : 'en')); const d = new Date().toISOString().slice(0, 10);
  const body = `${K.OV3_CSS}<div class="ov ov-lijst"><p class="crumbs"><a href="/">${esc(m.name)}</a> › ${esc(naam)}</p><p class="ov-eb"><i></i>${esc(T.cat)} · ${inCat.length} ${esc(T.n)}</p><h1>${esc(T.h1c(naam))}</h1><p class="kz-meta">${esc(T.upd)} <time datetime="${d}">${esc(datumW(m, d))}</time></p><p class="ov-lead lead">${esc(((CAT_INFO_W[m.id] || {})[naam] || '') + ' ' + T.lead)}</p>${ovChatW(m, naam, T.ph(naam), faq)}
<h2 class="ov-h">${esc(T.snel)}</h2><div class="ov-g">${snel.map(kaart).join('')}</div>
${rest.length ? `<h2 class="ov-h">${esc(T.rest)} ${esc(naam)}</h2><div class="ov-g">${rest.map(kaart).join('')}</div>` : ''}
<h2 class="ov-h">${esc(T.all)}</h2><div class="ov-cs">${cats.map(x => K.ovPil(catPad(m, x), x, x === naam)).join('')}</div></div>`;
  const url = base + catPad(m, naam);
  const ld = { '@context': 'https://schema.org', '@graph': [{ '@type': 'CollectionPage', name: T.h1c(naam), url, inLanguage: m.locale, dateModified: d, isPartOf: { '@type': 'WebSite', name: m.name, url: base } }, { '@type': 'BreadcrumbList', itemListElement: [{ '@type': 'ListItem', position: 1, name: m.name, item: base + '/' }, { '@type': 'ListItem', position: 2, name: naam, item: url }] }, { '@type': 'ItemList', name: T.h1c(naam), numberOfItems: volg.length, itemListElement: volg.map((i, k) => ({ '@type': 'ListItem', position: k + 1, url: base + '/' + i.slug, name: i.title })) }] };
  // titel: zoekterm voorop met één getal en vast bij elke crawl; voorbeelden uit de zoektermen gaven rommel ("4k usb-c monitor,", "laptops tablets, laptop") en wisselden met de populariteit van de dag (ZICHT dagcontrole 18 nov)
  const tit = T.h1c(naam) + ' (' + inCat.length + ')';
  return shell(m, { title: tit + ' | ' + m.name, desc: K.kortZin(((CAT_INFO_W[m.id] || {})[naam] || '') + ' ' + inCat.length + ' ' + T.n + '.', 155), path: catPad(m, naam), body, ld });
}

const BOTS = [['googlebot', /Googlebot|Google-InspectionTool|GoogleOther/i], ['bingbot', /bingbot/i], ['oai-searchbot', /OAI-SearchBot/i], ['chatgpt-user', /ChatGPT-User/i], ['gptbot', /GPTBot/i], ['claude', /Claude-User|Claude-SearchBot|ClaudeBot|anthropic-ai/i], ['perplexity', /Perplexity/i], ['applebot', /Applebot/i], ['meta', /meta-external|facebookexternalhit/i], ['amazonbot', /Amazonbot/i], ['duckduck', /DuckDuck/i]];
const botOf = ua => { for (const [n, re] of BOTS) if (re.test(ua)) return n; return /bot|crawl|spider|slurp|preview/i.test(ua) ? 'other' : ''; };
function source(req, q) { const u = String(q.get('utm_source') || '').toLowerCase(); if (u) return u.replace(/[^a-z0-9]/g, '').slice(0, 16); const r = String(req.headers.referer || ''); if (!r) return 'direct'; let h = ''; try { h = new URL(r).hostname.replace(/^www\./, ''); } catch (e) { return 'other'; } if (/whichtobuy|kaufberater/.test(h)) return 'intern'; if (/gemini\.google/.test(h)) return 'gemini'; if (/(^|\.)google\./.test(h)) return 'google'; if (/bing\.com/.test(h)) return 'bing'; if (/chatgpt|openai/.test(h)) return 'chatgpt'; if (/perplexity/.test(h)) return 'perplexity'; if (/copilot/.test(h)) return 'copilot'; if (/duckduckgo/.test(h)) return 'duckduckgo'; if (/pinterest/.test(h)) return 'pinterest'; if (/reddit/.test(h)) return 'reddit'; return 'other'; }
const ORG_BRON = ['google', 'bing', 'duckduckgo', 'chatgpt', 'perplexity', 'copilot', 'gemini']; // organisch: zoekmachines en AI-assistenten
async function count(m, req, q, slug) {
  const hits = []; const b = botOf(String(req.headers['user-agent'] || ''));
  if (b) hits.push(['c:wtb-' + m.id + '-bot-' + b, 1], ['c:wtb-' + m.id + '-botd-' + DAY() + '-' + b, 1]);
  else { const s = source(req, q); if (s !== 'intern') hits.push(['c:wtb-' + m.id + '-src-' + s, 1], ['c:wtb-' + m.id + '-d-' + DAY() + '-' + s, 1]); if (slug) { hits.push(['c:wtb-' + m.id + '-' + slug + '-view', 1]); if (ORG_BRON.includes(s)) hits.push(['c:wtb-' + m.id + '-' + slug + '-od-' + DAY() + '-' + s, 1]); } }
  try { if (hits.length) await kv.incrMany(hits); } catch (e) {}
}

// producten voor een route: term + zoekwoorden van de gekozen antwoorden, binnen de prijsgrenzen
async function advice(m, it, a, land) {
  if(it.decisionKind){const decision=guideDecision(it,a,land);return {subject:it.term,slug:it.slug,kws:decision.query,link:searchLink(m,decision.query),products:[],at:null,api:false,decision};}
  const opts = (it.questions || []).map((q, i) => (q.options || [])[a[i] || 0] || {});
  const kws = [it.term, ...opts.map(o => o.kw).filter(Boolean)].join(' ').replace(/\s+/g, ' ').trim();
  let min = 0, max = 1e9; opts.forEach(o => { if (o.min != null) min = Math.max(min, Number(o.min)); if (o.max != null) max = Math.min(max, Number(o.max)); });
  const out = { kws, subject: it.term || it.title, slug: it.slug, link: searchLink(m, kws), products: [], at: null, api: amzReady() };
  if (!amzReady()) return out;
  const tries = [kws, [it.term, opts[0] && opts[0].kw].filter(Boolean).join(' '), it.term];
  for (const k of [...new Set(tries)]) {
    try { const r = await amzSearch(m, k); if (!r) break; const ok = r.products.filter(p => p.image && (p.price == null || (p.price >= min && p.price <= max))); if (ok.length) { out.products = ok.slice(0, 3); out.at = r.at; if (k !== kws) out.relaxed = true; break; } } catch (e) { out.err = String(e.message).slice(0, 120); break; }
  }
  return out;
}

