      const vals = []; for (let i = 0; i < ks.length; i += 300) vals.push(...await kv.mget(...ks.slice(i, i + 300)).catch(() => []));
      const per = 3 + d7.length * (1 + ORG_BRON.length); const n = (i) => Number(vals[i]) || 0;
